import Database from 'better-sqlite3';
import path from 'path';
import fs from 'fs';

const dbPath = '/home/user/qwik-app/wiki.db';

// Ensure the directory for the db exists
const dbDir = path.dirname(dbPath);
if (!fs.existsSync(dbDir)) {
  fs.mkdirSync(dbDir, { recursive: true });
}

export const db = new Database(dbPath);

// Create table if it doesn't exist
db.exec(`
  CREATE TABLE IF NOT EXISTS revisions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    slug TEXT NOT NULL,
    user TEXT NOT NULL,
    timestamp INTEGER NOT NULL,
    content_length INTEGER NOT NULL
  )
`);

import { component$ } from '@builder.io/qwik';
import { routeLoader$ } from '@builder.io/qwik-city';
import fs from 'fs';
import path from 'path';
import { marked } from 'marked';

export const useWikiContent = routeLoader$(async ({ params, error }) => {
  const slug = params.slug;
  const filePath = path.join('/home/user/qwik-app/wiki-pages', `${slug}.md`);

  if (!fs.existsSync(filePath)) {
    throw error(404, 'Not Found');
  }

  try {
    const fileContent = await fs.promises.readFile(filePath, 'utf-8');
    const html = await marked.parse(fileContent);
    return {
      html,
    };
  } catch (err) {
    throw error(404, 'Not Found');
  }
});

export default component$(() => {
  const content = useWikiContent();

  return (
    <div class="wiki-content" dangerouslySetInnerHTML={content.value.html} />
  );
});

import { type RequestHandler } from '@builder.io/qwik-city';
import fs from 'fs';
import path from 'path';
import { db } from '../../../../lib/db';

export const onPost: RequestHandler = async ({ params, parseBody, redirect, json, request }) => {
  const slug = params.slug;
  const body = await parseBody() as any;

  const content = body?.content ?? '';
  const user = body?.user ?? '';

  // 1. Save the markdown text to /home/user/qwik-app/wiki-pages/[slug].md
  const pagesDir = '/home/user/qwik-app/wiki-pages';
  if (!fs.existsSync(pagesDir)) {
    fs.mkdirSync(pagesDir, { recursive: true });
  }
  const filePath = path.join(pagesDir, `${slug}.md`);
  await fs.promises.writeFile(filePath, content, 'utf-8');

  // 2. Insert a revision log entry into local SQLite database
  const timestamp = Date.now();
  const contentLength = content.length;

  const stmt = db.prepare(`
    INSERT INTO revisions (slug, user, timestamp, content_length)
    VALUES (?, ?, ?, ?)
  `);
  stmt.run(slug, user, timestamp, contentLength);

  // 3. Redirect or return JSON
  const contentType = request.headers.get('content-type') || '';
  const accept = request.headers.get('accept') || '';
  if (contentType.includes('application/json') || accept.includes('application/json')) {
    throw json(200, { success: true });
  }

  throw redirect(303, `/wiki/${slug}`);
};

import { type RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../../lib/db';

export const onGet: RequestHandler = async ({ params, json }) => {
  const slug = params.slug;

  const stmt = db.prepare(`
    SELECT id, slug, user, timestamp, content_length
    FROM revisions
    WHERE slug = ?
    ORDER BY timestamp DESC
  `);
  const rows = stmt.all(slug);

  const revisions = rows.map((row: any) => ({
    id: Number(row.id),
    slug: String(row.slug),
    user: String(row.user),
    timestamp: Number(row.timestamp),
    content_length: Number(row.content_length),
  }));

  throw json(200, revisions);
};

